-- The Endocrine System — Batch 3 — Thyroid/Parathyroid + Adrenal Glands
-- Original Praxist Prep questions, grounded in the subject reference textbook; scope verified vs AAMC 2026 outline.
-- Idempotent: deletes only this batch's subtopics, then re-inserts. question_attempts / distractor_metadata cascade.

DELETE FROM questions WHERE topic = 'The Endocrine System' AND subtopic IN ('Adrenal Glands', 'Thyroid & Parathyroid');

-- Q1 [Thyroid & Parathyroid] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Thyroid & Parathyroid', 'A gland in the front of the neck releases two iodine-containing hormones, but only after the anterior pituitary sends it a stimulating signal. Once in the blood, these hormones enter cells throughout the entire body and bind receptors on the mitochondria and in the nucleus. Which of the following whole-body parameters is established by this gland''s hormones?', '[{"label": "A", "text": "Resting energy expenditure"}, {"label": "B", "text": "Concentration of calcium in the blood"}, {"label": "C", "text": "Concentration of glucose in the blood"}, {"label": "D", "text": "Intensity of the fight-or-flight response"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is A because the described gland is the thyroid, whose iodine-containing hormones T3 and T4 are released in response to thyroid-stimulating hormone (TSH) from the anterior pituitary; T3 and T4 enter cells throughout the body and bind intracellular receptors on the mitochondria and in the nucleus, where they raise nutrient breakdown, oxygen consumption, and ATP output. (Choice A) is correct: the sum of this activity at rest is the body''s basal metabolic rate, described here as resting energy expenditure, the amount of energy the body uses at rest, and thyroid hormones are the metabolic hormones that set it. (Choice B) is incorrect: the concentration of calcium in the blood is established by parathyroid hormone (which raises it) and calcitonin (which lowers it) acting on bone, kidney, and intestine, not by the iodine-containing metabolic hormones T3/T4 described in the stem. (Choice C) is incorrect: the concentration of glucose in the blood is set chiefly by pancreatic insulin and glucagon (with cortisol raising it); although thyroid hormones initiate transcription of genes for glucose oxidation inside cells, they do not establish the blood glucose level itself. (Choice D) is incorrect: the intensity of the fight-or-flight response is driven by epinephrine and norepinephrine from the adrenal medulla, an acute stress function distinct from the sustained, body-wide metabolic set point governed by thyroid hormones. This is a Skill 1 (Knowledge of Scientific Concepts) item because it requires recognizing the thyroid''s characteristic role in setting basal metabolic rate from a description of its control relationship and broad intracellular action.', 'easy', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 1, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'adjacent_fact', 'same-region hormone with a different set point (PTH/calcitonin regulate blood calcium, not energy expenditure)' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'conflating thyroid-driven intracellular glucose oxidation with blood glucose homeostasis (insulin/glucagon)' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'substituting an unrelated systemic endocrine parameter (adrenal medulla epinephrine/norepinephrine, fight-or-flight)' FROM q;

-- Q2 [Thyroid & Parathyroid] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Thyroid & Parathyroid', 'A patient''s cells show a sustained rise in the hormone that binds intracellular receptors on mitochondria and drives transcription of genes for nutrient breakdown. Which whole-body consequence is most expected?', '[{"label": "A", "text": "Reduced blood calcium concentration"}, {"label": "B", "text": "Higher oxygen consumption and heat output"}, {"label": "C", "text": "Lowered fasting blood glucose"}, {"label": "D", "text": "Decreased sodium reabsorption by kidneys"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is B because the hormone described—thyroid hormone (T3/T4), which binds intracellular receptors on mitochondria and initiates transcription of genes for nutrient breakdown and glucose oxidation—raises the body''s basal metabolic rate. When present in excess, it increases nutrient breakdown and the use of oxygen to produce ATP; because this ATP production is inefficient, abnormally increased heat is released as a byproduct (the calorigenic effect), raising body temperature. Thus elevated levels drive up oxygen consumption and heat output together. (Choice B) is correct: elevated thyroid hormone increases cellular respiration, so oxygen use climbs, and the inefficient ATP synthesis releases surplus heat, elevating metabolic rate and body temperature. (Choice A) is incorrect: blood calcium is lowered by calcitonin (from the thyroid''s parafollicular cells) and raised by parathyroid hormone; calcium homeostasis is a separate hormonal axis from the metabolic-rate hormone described, and elevated metabolic hormone does not itself drive calcium down. (Choice C) is incorrect: fasting blood glucose is lowered chiefly by insulin; the metabolic hormone described actually promotes glucose oxidation and, in excess, tends to accompany catabolism rather than a hypoglycemic set point, so predicting lowered glucose misattributes insulin''s role. (Choice D) is incorrect: renal sodium handling is governed largely by aldosterone (and, for water, ADH); the calorigenic metabolic hormone does not act primarily on sodium reabsorption, so this confuses the mineralocorticoid axis with the metabolic one. This question requires Skill 2 reasoning because the student must map a described mechanism onto its downstream physiological effect—predicting increased oxygen use and heat from an elevated metabolic hormone—rather than recalling a stated definition.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'adjacent_fact', 'same-gland-different-hormone (calcitonin/PTH calcium role attributed to the metabolic thyroid hormone)' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'metabolic-hormone-equals-glucose-lowering (conflates thyroid hormone with insulin)' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'wrong-axis (attributes aldosterone/ADH renal sodium role to the metabolic hormone)' FROM q;

-- Q3 [Thyroid & Parathyroid] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Thyroid & Parathyroid', 'A 26-year-old woman reports that over several months she has felt uncomfortably warm even in cool rooms, her resting pulse is persistently rapid, and she has lost 6 kg despite eating more than usual and feeling restless and "wired." Which endocrine change best accounts for this cluster of findings?', '[{"label": "A", "text": "Sustained overproduction of adrenal epinephrine"}, {"label": "B", "text": "Deficient secretion of triiodothyronine and thyroxine"}, {"label": "C", "text": "Excess secretion of triiodothyronine and thyroxine"}, {"label": "D", "text": "Chronic oversecretion of parathyroid hormone"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because the thyroid hormones triiodothyronine (T3) and thyroxine (T4) set the basal metabolic rate, so an abnormally elevated blood level of these hormones drives the whole cluster described: increased metabolic rate produces excessive body heat and heat intolerance, catabolism of energy stores causes weight loss despite increased appetite, and sympathetic-like stimulation raises heart rate and produces restlessness. (Choice C) is correct: elevated T3/T4 raises the metabolic rate, which the textbook lists as causing excessive body heat and sweating, weight loss, and increased heart rate, matching every finding in the scenario. (Choice B) is incorrect: too little T3/T4 lowers the metabolic rate, producing the opposite profile of weight gain, cold extremities, and reduced activity, so a deficiency cannot explain heat intolerance, weight loss, and tachycardia. (Choice A) is incorrect: adrenal epinephrine does accelerate heart rate and mobilize glucose during the fight-or-flight response, but it acts as a brief, acute surge rather than the sustained months-long state of hypermetabolism and net weight loss described here. (Choice D) is incorrect: parathyroid hormone regulates blood calcium by raising it, and its excess disturbs calcium and bone rather than metabolic rate, body temperature, and appetite-independent weight loss. To answer, the student had to reason from the presenting signs back to which hormone''s output level was disturbed and in which direction, rather than recall a stated definition.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Confuses the direction of hormone imbalance, attributing a hypermetabolic presentation to a hormone deficiency (hypothyroid profile) rather than excess' FROM q
  UNION ALL
  SELECT id, 'A', 'adjacent_fact', 'Latches onto the overlapping sign of tachycardia and picks the fight-or-flight catecholamine, ignoring that epinephrine acts acutely and does not explain sustained hypermetabolism and weight loss' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Selects another thyroid-region hormone but one governing calcium homeostasis, conflating ''thyroid area'' hormones and missing that PTH does not control metabolic rate or body temperature' FROM q;

-- Q4 [Thyroid & Parathyroid] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Thyroid & Parathyroid', 'A 44-year-old patient reports persistent fatigue, unexplained weight gain, and feeling cold even in a warm room. On examination, both heart rate and respiratory rate are noticeably slower than normal. Which underlying endocrine state best accounts for this combination of findings?', '[{"label": "A", "text": "Parathyroid glands secreting insufficient hormone"}, {"label": "B", "text": "Overactive thyroid gland from follicular-cell overstimulation"}, {"label": "C", "text": "Adrenal cortex hypersecreting cortisol"}, {"label": "D", "text": "Underactive thyroid gland, reducing metabolic hormone output"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is D because the thyroid hormones T3 and T4 set the body''s basal metabolic rate, drive calorigenic heat production, and increase the body''s sensitivity to catecholamines that accelerate the heartbeat; when their output falls, metabolism, heat generation, and cardiorespiratory drive all decline. This produces exactly the described cluster: low metabolic rate, weight gain, cold intolerance, lethargy, and a slowed heart and respiratory rate. (Choice D) is correct: an underactive thyroid gland lowers circulating T3 and T4, and OpenStax lists a low metabolic rate, weight gain, cold extremities, and reduced activity as the hallmark presentation of this deficiency state. (Choice B) is incorrect: an overactive thyroid gland raises T3 and T4, which increases metabolic rate and body heat and accelerates the heart rate, yielding heat intolerance, weight loss, and tachycardia—the opposite of the findings described, so it is the reversed-direction trap. (Choice C) is incorrect: adrenal hypersecretion of cortisol causes Cushing''s disease, which does produce lipid accumulation and weight changes, but it is marked by high blood glucose and central fat deposits rather than cold intolerance and a slowed heart rate, so the matching symptom is only superficial. (Choice A) is incorrect: deficient parathyroid hormone lowers blood calcium and causes muscle twitching, cramping, and spasms; although the parathyroid glands sit within the thyroid region, their hormone governs calcium balance, not basal metabolism, so it cannot explain this metabolic-slowing picture. This item requires Skill 2 reasoning because the student must map an unlabeled clinical cluster onto the correct hormonal direction and gland rather than recall a stated definition.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Confuses hyperthyroidism with hypothyroidism, selecting the elevated-hormone state for a low-hormone symptom cluster' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'Anchors on weight gain and picks Cushing''s/cortisol excess, ignoring the cold intolerance and bradycardia that point to metabolic slowing' FROM q
  UNION ALL
  SELECT id, 'A', 'misconception', 'Associates any deficiency in the thyroid region with the parathyroid glands, conflating calcium regulation with basal metabolism' FROM q;

-- Q5 [Thyroid & Parathyroid] hard skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Thyroid & Parathyroid', 'A dietary survey finds that residents of a landlocked region who do not use iodized salt have chronically enlarged thyroid glands. Blood tests reveal their circulating triiodothyronine (T3) and thyroxine (T4) are persistently low. Which laboratory finding for a pituitary-derived hormone best explains why the gland became enlarged?', '[{"label": "A", "text": "Thyroid-stimulating hormone is suppressed"}, {"label": "B", "text": "Thyroid-stimulating hormone is elevated"}, {"label": "C", "text": "Thyrotropin-releasing hormone is suppressed"}, {"label": "D", "text": "Calcitonin is elevated"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is B because iodine is an essential substrate for building T3 and T4, so a deficiency blocks their synthesis and drops their circulating levels; because rising T3 and T4 normally inhibit the anterior pituitary through negative feedback, chronically low T3 and T4 remove that inhibition, and the pituitary secretes thyroid-stimulating hormone (TSH) in increasing amounts. The sustained TSH hyperstimulation drives thyroglobulin and colloid to accumulate in the follicles, enlarging the gland into a goiter. (Choice B) is correct: with negative feedback lifted by the low T3 and T4, TSH from the anterior pituitary rises and its chronic trophic drive on the follicles produces the enlargement. (Choice A) is incorrect: suppressed TSH would occur when T3 and T4 are high (as in a T4-secreting tumor), which would signal the pituitary to shut down; low TSH provides no growth stimulus and would leave the gland small, the opposite of the observed goiter. (Choice C) is incorrect: thyrotropin-releasing hormone (TRH) is a hypothalamic, not a pituitary, hormone, so it does not answer the question as posed; moreover, low thyroid hormone relieves feedback on the hypothalamus, so TRH rises rather than falls. (Choice D) is incorrect: calcitonin is secreted by the thyroid parafollicular (C) cells to lower blood calcium and is regulated by serum calcium, not by iodine status or the TSH feedback axis, so it neither reflects the deficiency nor drives follicular growth. Answering requires chaining the loss of substrate to falling hormone output, then to loss of feedback inhibition, and finally to the pituitary response that enlarges the gland, rather than recalling a single definition.', 'hard', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 100, NULL)
  RETURNING id
)
