-- Q6 [Thyroid & Parathyroid] easy skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Thyroid & Parathyroid', 'Residents of a landlocked mountain region who eat no seafood and use non-fortified salt frequently develop enlarged thyroid glands (goiter), even though their follicular cells contain normal amounts of tyrosine and thyroglobulin. Which dietary component are these individuals most likely lacking?', '[{"label": "A", "text": "Cholesterol"}, {"label": "B", "text": "Calcium"}, {"label": "C", "text": "Iodine"}, {"label": "D", "text": "Tryptophan"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because thyroid hormones (T3 and T4) are built by covalently attaching iodine atoms to the tyrosine residues of thyroglobulin in the follicular cells; when dietary iodine is scarce, the follicular cells cannot complete synthesis despite having plenty of tyrosine and thyroglobulin, so hormone output falls, TSH rises, and the gland enlarges into a goiter. (Choice C) is correct: iodine is the essential and unique component of thyroid hormone, and regions without seafood or iodized salt are the classic setting for iodine-deficiency goiter. (Choice B) is incorrect: calcium is regulated by the thyroid''s parafollicular (C) cells via calcitonin, but calcium is not incorporated into T3/T4, so a calcium shortage would not block their synthesis or cause goiter. (Choice A) is incorrect: cholesterol is the precursor for steroid hormones such as cortisol and the sex steroids, not for the tyrosine-derived thyroid hormones. (Choice D) is incorrect: tryptophan is the amino-acid precursor for melatonin and serotonin, whereas thyroid hormone is built on tyrosine, so tryptophan is not the limiting building block here. This question requires recognizing the specific element that must be supplied to make thyroid hormone, a Skill 1 recall of scientific knowledge.', 'easy', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 1, 60, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'adjacent_fact', 'same-gland confusion: calcium is regulated by the thyroid''s parafollicular cells (calcitonin), so a student links the thyroid to calcium' FROM q
  UNION ALL
  SELECT id, 'A', 'misconception', 'precursor confusion: assumes all hormones derive from cholesterol, the steroid-hormone precursor' FROM q
  UNION ALL
