-- Q7 [Thyroid & Parathyroid] easy skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Thyroid & Parathyroid', 'A routine blood panel shows a patient''s ionized calcium concentration has fallen below the normal reference range. In response, an endocrine gland in the neck secretes a peptide hormone that acts on bone, kidney, and intestine to restore calcium toward normal. Which hormone is secreted?', '[{"label": "A", "text": "Thyroxine"}, {"label": "B", "text": "Calcitonin"}, {"label": "C", "text": "Aldosterone"}, {"label": "D", "text": "Parathyroid hormone"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is D because a fall in blood calcium is corrected by parathyroid hormone, the peptide secreted by the chief cells of the parathyroid glands, which stimulates osteoclast-driven calcium release from bone, increases calcium reabsorption in the kidney tubules, and activates vitamin D (calcitriol) to enhance intestinal calcium absorption. (Choice D) is correct: parathyroid hormone is released specifically in response to low blood calcium and raises it through its combined actions on bone, kidney, and intestine. (Choice B) is incorrect: calcitonin, produced by the parafollicular (C) cells of the thyroid, is secreted when blood calcium is high and lowers it by inhibiting osteoclasts; it acts in the opposite direction from what a low-calcium state requires. (Choice C) is incorrect: aldosterone, a mineralocorticoid from the adrenal cortex, regulates blood sodium and potassium and fluid balance, not blood calcium. (Choice A) is incorrect: thyroxine, the thyroid''s metabolic hormone, sets basal metabolic rate and promotes bone growth but is not the hormone that acutely corrects a low blood calcium level. This is a Skill 1 item because it requires recalling the source and function of the hormone that maintains blood calcium homeostasis.', 'easy', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 1, 45, NULL)
  RETURNING id
)
