WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Adrenal Glands', 'During a prolonged emotional crisis, a person''s blood glucose rises as stored glycogen, fats, and proteins are broken down to supply fuel. Which hormone is chiefly responsible for this sustained glucose mobilization during long-term stress?', '[{"label": "A", "text": "Aldosterone"}, {"label": "B", "text": "Cortisol"}, {"label": "C", "text": "Epinephrine"}, {"label": "D", "text": "Glucagon"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is B because cortisol is the principal glucocorticoid secreted by the zona fasciculata of the adrenal cortex, and in response to long-term stress it promotes the catabolism of glycogen, triglycerides, and muscle protein so those raw materials can be used to synthesize glucose, sustaining elevated blood glucose as a ready fuel. (Choice A) is incorrect: aldosterone is a mineralocorticoid that regulates sodium and potassium balance, blood volume, and blood pressure; it does not mobilize glucose or drive nutrient catabolism. (Choice B) is correct: cortisol is the hormone that raises blood glucose during sustained stress by driving the breakdown of stored glycogen, fats, and proteins for gluconeogenesis. (Choice C) is incorrect: epinephrine does raise blood glucose, but it is the adrenal-medulla catecholamine of the acute, short-term fight-or-flight response and acts mainly by converting liver and muscle glycogen to glucose, so it does not account for the sustained mobilization of fats and proteins seen in prolonged stress. (Choice D) is incorrect: glucagon raises blood glucose, but it is a pancreatic hormone whose principal action is stimulating hepatic glycogen breakdown and gluconeogenesis; it is not the hormone that drives the broad, sustained catabolism of stored triglycerides and muscle protein during long-term stress. This question assesses Skill 1 by requiring the student to recall and identify the hormone that matches a described sustained-stress and glucose-mobilization scenario.', 'easy', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 1, 60, NULL)
  RETURNING id
)
