-- Q16 [Adrenal Glands] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Adrenal Glands', 'A patient with a chronic inflammatory condition takes daily high doses of a synthetic steroid drug for several months. The drug binds and activates the same intracellular receptors as the principal stress steroid made by the outer region of the adrenal glands — including the receptors in the hypothalamus and pituitary that sense that steroid''s level. After several months, what happens to the anterior pituitary''s output of the tropic hormone that normally drives the adrenal cortex, and to the size of the cortex itself?', '[{"label": "A", "text": "Tropic hormone rises; the cortex atrophies"}, {"label": "B", "text": "Tropic hormone rises; the cortex enlarges"}, {"label": "C", "text": "Tropic hormone falls; the cortex atrophies"}, {"label": "D", "text": "Tropic hormone falls; the cortex enlarges"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because the synthetic drug occupies the same glucocorticoid receptors as cortisol and therefore mimics its downstream effects, including the negative-feedback signal that suppresses the hypothalamic-pituitary-adrenal (HPA) axis; the hypothalamus and anterior pituitary sense an ''adequate'' glucocorticoid state and reduce their signaling, so the pituitary''s tropic hormone (ACTH) falls. Because ACTH is also the trophic stimulus that maintains the cortex, its chronic withdrawal starves the zona fasciculata of stimulation and the cortex atrophies. (Choice C) is correct: high sustained glucocorticoid-receptor activation drives negative feedback that lowers ACTH, and loss of trophic ACTH support causes the adrenal cortex to shrink. (Choice B) is incorrect: rising tropic hormone with an enlarging cortex describes an ACTH-secreting pituitary tumor (a cause of Cushing''s disease), in which the pituitary is the source of excess signal; here the excess glucocorticoid comes from an outside drug, which suppresses—rather than raises—ACTH, so this is a partial-truth trap that confuses two different high-cortisol scenarios. (Choice A) is incorrect: it correctly predicts cortical atrophy but reverses the feedback direction, since negative feedback from a glucocorticoid signal lowers ACTH rather than raising it. (Choice D) is incorrect: it correctly predicts that ACTH falls, but a fall in trophic ACTH cannot enlarge the cortex; without ACTH stimulation the cortex loses mass. Skill 2: this item requires chaining exogenous receptor activation to feedback suppression of ACTH and then to loss of trophic support and cortical atrophy, distinguishing a drug-driven perturbation from a tumor-driven one.', 'hard', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 100, NULL)
  RETURNING id
)
