-- Q17 [Adrenal Glands] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Adrenal Glands', 'A diuretic drug binds and blocks receptors on the principal cells of the distal nephron. After the patient takes it, urinalysis shows that Na+ excretion has risen while K+ is now retained in the blood. The normal action of which adrenal cortex hormone is this drug opposing?', '[{"label": "A", "text": "Aldosterone"}, {"label": "B", "text": "Cortisol"}, {"label": "C", "text": "Atrial natriuretic peptide"}, {"label": "D", "text": "Antidiuretic hormone"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is A because the drug produces the exact opposite of aldosterone''s normal effect on the distal nephron: aldosterone drives Na+ reabsorption while simultaneously driving K+ secretion into the forming urine, so blocking its receptor causes Na+ to be lost in the urine and K+ to be retained in the blood, precisely the pattern described. (Choice A) is correct: aldosterone, the major mineralocorticoid of the adrenal cortex, acts on principal cells to increase Na+ recovery and increase K+ excretion, so a receptor blocker reverses both effects, yielding Na+ wasting with K+ retention. (Choice B) is incorrect: cortisol is a glucocorticoid whose primary role is regulating glucose and fat metabolism and the stress response, not the coupled Na+-reabsorption/K+-secretion action at distal-nephron principal cells described here. (Choice C) is incorrect: atrial natriuretic peptide already promotes Na+ excretion (it inhibits aldosterone), so blocking it would tend to retain Na+, the opposite of the observed rise in Na+ excretion, and it is secreted by cardiac atria, not the adrenal cortex. (Choice D) is incorrect: antidiuretic hormone governs water reabsorption via the posterior pituitary, not the coupled Na+/K+ handling described, and blocking it would primarily increase water loss rather than reverse Na+ and K+ movement. Skill 2: this item requires translating an observed, reversed electrolyte-handling pattern back to the hormone whose defined mechanism, when opposed, produces it.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
