-- Q21 [Adrenal Glands] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Adrenal Glands', 'A driver narrowly avoids a highway collision. In the seconds afterward, which combination of changes would best characterize the acute physiological response mobilizing her body for immediate exertion?', '[{"label": "A", "text": "Slowed heart rate, narrowed airways, lowered blood glucose"}, {"label": "B", "text": "Faster heart rate, widened airways, elevated blood glucose"}, {"label": "C", "text": "Elevated blood glucose, slowed heart rate, narrowed airways"}, {"label": "D", "text": "Sodium retention, increased blood volume, raised blood pressure"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is B because an acute, short-term stressor triggers the sympathomedullary (SAM) pathway, prompting the adrenal medulla''s chromaffin cells to release the catecholamines epinephrine and norepinephrine into circulation; these hormones increase heart rate, dilate the airways to raise blood oxygen, and signal the liver and skeletal muscle to convert glycogen into glucose, raising blood glucose to fuel immediate exertion. (Choice B) is correct: rising heart rate, bronchodilation, and elevated blood glucose are precisely the systemic effects of medullary catecholamines during the fight-or-flight (alarm) reaction. (Choice A) is incorrect: a slowed heart rate, constricted airways, and falling blood glucose describe the opposite, rest-and-digest direction (parasympathetic tone plus insulin action), which is suppressed—not activated—during acute stress. (Choice C) is incorrect: it correctly pairs elevated glucose with stress but reverses the cardiac and respiratory effects; catecholamines speed the heart and open the airways rather than slowing the heart and narrowing bronchioles. (Choice D) is incorrect: sodium retention, expanded blood volume, and raised pressure are effects of aldosterone from the adrenal cortex (a mineralocorticoid governing fluid balance) acting over minutes to hours, not the seconds-scale medullary catecholamines that drive the rapid exertion response. Reasoning from the described acute perturbation to the coordinated set of downstream target-organ effects, rather than recalling a single fact, is the Skill 2 demand here.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
