  SELECT id, 'A', 'reversed_relationship', 'Applies the opposite (parasympathetic/rest-and-digest) direction to every target organ' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'Keeps the correct glucose effect but reverses the cardiac and respiratory directions' FROM q
