  UNION ALL
  SELECT id, 'D', 'misconception', 'attributes both hormones to the medulla, ignoring the cortex''s steroids' FROM q;

-- Q23 [Adrenal Glands] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Adrenal Glands', 'During a near-miss car accident, a driver''s blood glucose spikes within seconds, well before any change in pancreatic secretion could take effect. Which hormone drives this near-instantaneous rise, and by what action?', '[{"label": "A", "text": "Insulin, releasing glucose from adipose tissue"}, {"label": "B", "text": "Glucagon, breaking down stored glycogen"}, {"label": "C", "text": "Cortisol, synthesizing new glucose molecules"}, {"label": "D", "text": "Epinephrine, breaking down stored glycogen"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is D because the scenario describes an acute, seconds-scale stress response driven by the sympathetic nervous system, which directly stimulates the chromaffin cells of the adrenal medulla to release epinephrine; epinephrine signals the liver and skeletal muscle to convert stored glycogen into glucose (glycogenolysis), producing the near-instantaneous rise in blood glucose. (Choice D) is correct: epinephrine, a catecholamine from the adrenal medulla, is released via a rapid neural pathway and triggers glycogen breakdown, matching both the source and the mechanism required by the described time course. (Choice B) is incorrect: glucagon also raises blood glucose through glycogenolysis, but it originates from the alpha cells of the pancreas and is secreted in response to declining glucose during fasting, not through the seconds-scale sympathetic pathway that the stem''s timing excludes. (Choice C) is incorrect: cortisol, an adrenal cortex glucocorticoid, raises glucose largely by promoting gluconeogenesis and nutrient catabolism during long-term stress via the slower CRH-ACTH pathway, so both its speed and its stated mechanism (synthesizing new glucose) are wrong for an immediate spike. (Choice A) is incorrect: insulin lowers rather than raises blood glucose and promotes glycogen storage, and glucose is not mobilized from adipose tissue, so this reverses the direction of the effect. Answering requires interpreting the described time course and stress context to deduce which gland is activated and which biochemical action fits, rather than recalling a definition.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
