-- Q24 [Adrenal Glands] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Adrenal Glands', 'During a fright, a sympathetic preganglionic fiber synapses directly on chromaffin cells in the core of the adrenal gland, which then empty their secretory product into the capillaries draining the gland rather than onto a specific postsynaptic target. Compared with a postganglionic sympathetic neuron releasing its transmitter at a discrete synapse, how does this arrangement most likely shape the onset and reach of the adrenal core''s output?', '[{"label": "A", "text": "Rapid onset, with effects spread across many distant organs at once"}, {"label": "B", "text": "Delayed onset, but effects confined to one target organ"}, {"label": "C", "text": "Rapid onset, but effects restricted to a single adjacent organ"}, {"label": "D", "text": "Delayed onset, then permanent effects on all tissues"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is A because the chromaffin cells are triggered by a sympathetic nerve impulse, giving the response the rapid onset of the nervous system, yet they dump their secretory product into the bloodstream rather than at a synapse, so those molecules travel widely and act on distant cells throughout the body at once, combining nervous-system speed with endocrine breadth. (Choice A) is correct: neural stimulation drives fast release, and because the product enters the systemic circulation it exerts effects broadly on many organs simultaneously, exactly as the fight-or-flight response requires. (Choice B) is incorrect: it treats the output as a slow hormone acting on only one organ, but a nerve impulse triggers the release, so onset is fast, not delayed, and blood-borne delivery reaches many organs, not one. (Choice C) is incorrect: it correctly recognizes the fast onset but wrongly assumes the product stays local like a neurotransmitter at a synapse, ignoring that release into the bloodstream carries it to widely distributed targets. (Choice D) is incorrect: it confuses the medullary output with the slow, sustained steroid response of the adrenal cortex; the medulla''s catecholamines have a very short half-life (about one minute) and are cleared quickly rather than acting permanently. To arrive at this answer, a student must reason from the described anatomy—a nerve-triggered cell secreting into blood—rather than recall a memorized definition, integrating that neural triggering yields speed while circulatory delivery yields body-wide reach.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 80, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'assumes all hormonal signaling is slow and narrowly targeted, reversing both the onset (nerve-triggered = fast) and the reach (blood-borne = broad)' FROM q
  UNION ALL
