-- Q25 [Adrenal Glands] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Adrenal Glands', 'A patient has a tumor in the inner region of one adrenal gland whose cells are anatomically continuous with postganglionic sympathetic neurons. The tumor autonomously secretes its signaling molecule into the blood. Which cluster of findings would this tumor most likely produce?', '[{"label": "A", "text": "Central obesity, hyperglycemia, and immune suppression"}, {"label": "B", "text": "Hypertension with sodium retention and hypokalemia"}, {"label": "C", "text": "Hypertension, tachycardia, and hyperglycemia"}, {"label": "D", "text": "Deepening voice and increased body hair"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because the tumor arises in the adrenal medulla—the inner region composed of chromaffin cells that are modified postganglionic sympathetic neurons—so its secreted product is the catecholamines epinephrine and norepinephrine. These hormones increase heart rate, pulse, and blood pressure and signal the liver and skeletal muscle to convert glycogen into glucose, raising blood glucose. (Choice C) is correct: hypertension, tachycardia, and elevated blood glucose together map directly onto the fight-or-flight actions of medullary catecholamines, and no other adrenal product produces that exact triad. (Choice B) is incorrect: sodium retention with potassium loss reflects excess aldosterone, a mineralocorticoid made by the zona glomerulosa of the adrenal cortex, not by the medulla; aldosterone drives Na+ retention and K+ excretion but does not cause tachycardia or hyperglycemia. (Choice A) is incorrect: central (truncal) adiposity, hyperglycemia, and immune suppression describe cortisol excess (Cushing pattern) from the zona fasciculata of the cortex; although both cortisol and catecholamines can raise glucose, the fat redistribution and immunosuppression are glucocorticoid-specific and do not arise from the medulla. (Choice D) is incorrect: virilizing signs such as a deepening voice and increased body hair result from excess androgens produced by the zona reticularis of the adrenal cortex, again a cortical rather than medullary product. A Skill 2 solver must first localize the tumor to the medulla from the anatomical clues, identify catecholamines as the secreted product, and then predict the downstream cardiovascular and metabolic picture, discriminating it from the three cortical-excess syndromes.', 'hard', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 100, NULL)
  RETURNING id
)
